param([Parameter(Mandatory)][string]$Executable,[Parameter(Mandatory)][string]$ProviderExecutable,[Parameter(Mandatory)][string]$ProjectRoot,[Parameter(Mandatory)][string]$ScratchRoot)
$ErrorActionPreference='Stop';$checks=0;$service=$null;$provider=$null
$root=Join-Path $ScratchRoot ('memory-workshop-'+[Guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Force $root|Out-Null
$env:HIBERNATION_SESSION_KEY='workshop-synthetic-session';$headers=@{Authorization='Bearer '+$env:HIBERNATION_SESSION_KEY};$ready=Join-Path $root ready.json;$configPath=Join-Path $root config.json
function Check([bool]$Value,[string]$Name){if(!$Value){throw "CHECK FAILED: $Name"};$script:checks++;Write-Output "PASS $Name"}
function Await([scriptblock]$Probe,[string]$Name,[int]$Seconds=30){$end=[DateTime]::UtcNow.AddSeconds($Seconds);while([DateTime]::UtcNow-lt$end){if(& $Probe){return};Start-Sleep -Milliseconds 40};throw "TIMEOUT: $Name"}
function Api($Path,$Data=$null){$options=@{Uri=$script:origin+$Path;Headers=$headers;TimeoutSec=15};if($null-ne$Data){$options.Method='Post';$options.ContentType='application/json; charset=utf-8';$options.Body=[Text.Encoding]::UTF8.GetBytes(($Data|ConvertTo-Json -Depth 60 -Compress))};Invoke-RestMethod @options}
function Error-Code($Path,$Data,[int]$Code){$r=Invoke-WebRequest -Uri ($script:origin+$Path) -Headers $headers -Method Post -ContentType 'application/json' -Body ([Text.Encoding]::UTF8.GetBytes(($Data|ConvertTo-Json -Depth 60))) -SkipHttpErrorCheck;Check ($r.StatusCode-eq$Code) "bounded rejection $Path ($Code)"}
function Start-Backend{$script:service=Start-Process -FilePath $Executable -ArgumentList ('--config "'+$configPath+'" --ready-file "'+$ready+'"') -WindowStyle Hidden -PassThru;Await {if($service.HasExited){throw 'workshop host exited'};if(Test-Path -LiteralPath $ready){return (Get-Content -LiteralPath $ready -Raw|ConvertFrom-Json).pid-eq$service.Id};$false} ready;$script:origin='http://127.0.0.1:'+((Get-Content -LiteralPath $ready -Raw|ConvertFrom-Json).port)}
function Stop-Backend{$null=Api '/api/shutdown' @{};Check ($service.WaitForExit(15000)-and$service.ExitCode-eq0) 'clean backend exit'}
function Job($Id){(Api '/api/memory-workshop').jobs|Where-Object id -eq $Id}
function Create($Type,$Extra=@{}){$body=@{type=$Type;request_id=[Guid]::NewGuid().ToString('N')};foreach($k in $Extra.Keys){$body[$k]=$Extra[$k]};Api '/api/memory-workshop/jobs' $body}
function Message($Text){$r=Api '/api/message' @{request_id=[Guid]::NewGuid().ToString('N');text=$Text};Await {!(Api '/api/state').busy} dialogue;return $r.event_id}
try{
 $cfg=Get-Content (Join-Path $ProjectRoot config/example.json) -Raw|ConvertFrom-Json -AsHashtable
 $cfg.dataRoot=Join-Path $root data;$cfg.characterRoot=Join-Path $ProjectRoot character;$cfg.uiRoot=Join-Path $ProjectRoot ui;$cfg.pluginRoot=Join-Path (Split-Path $Executable) plugins;$cfg.plugins=@{};$cfg.computer=@{enabled=$false};$cfg.solitudeIntervalMs=604800000;$cfg.idleBeforeSolitudeMs=86400000;$cfg.profiles=@($cfg.profiles[0]);$cfg.review=@{enabled=$false};$cfg.memoryWorkshop=@{enabled=$true;backupRoot=(Join-Path $root "备份'目录")};$cfg.dashboard=@{pluginOrder=@('tts','widget');sections=@{models=@('profiles','review','budget')}};$cfg|ConvertTo-Json -Depth 60|Set-Content $configPath -Encoding utf8
 Start-Backend
 $view=Api '/api/memory-workshop';Check ($view.enabled-and!$view.training_available-and!$view.memory_contents_visible) 'owner management reports real deferred training and hidden contents'
 $ids=@();foreach($i in 1..4){$ids+=Message ("WORKSHOP_ORIGINAL_$i "+('这是未结束的合成故事，先保留不同人物的说法和纠正。'*55))};foreach($i in 1..3){$null=Message "短暂相处$i"}
 $preview=Api '/api/memory-workshop/preview' @{limit=128;minBytes=2000};Check ($preview.selected-ge4-and!$preview.PSObject.Properties['sources']) 'preview returns counts without exposing original memory or ids'
 $settings=(Api '/api/dashboard').settings;$settings.dashboard.pluginOrder=@('widget','widget');Error-Code '/api/settings' @{settings=$settings} 400
 $settings=(Api '/api/dashboard').settings;$settings.memoryWorkshop.backupRoot=$cfg.dataRoot;Error-Code '/api/settings' @{settings=$settings} 400
 $settings=(Api '/api/dashboard').settings;Check ($settings.dashboard.sections.models[0]-eq'profiles') 'presentation order is preserved by dashboard configuration'
 $request=@{type='distill';request_id='idempotent-distillation';limit=128;minBytes=2000};$task=Api '/api/memory-workshop/jobs' $request;$duplicate=Api '/api/memory-workshop/jobs' $request;Check ($duplicate.duplicate-and$duplicate.id-eq$task.id) 'job creation is idempotent'
 Error-Code '/api/memory-workshop/jobs' @{type='backup';request_id='bad';destination=$cfg.dataRoot} 400
 $plan=@{baseModel='base-model@fixture-version';adapterPath='E:/fixture/previous-lora';checkpointPath='E:/fixture/checkpoint-100';steps=1000;saveEvery=100}
 $training=Create lora @{plan=$plan};$j=Job $training.id;Check ($j.status-eq'awaiting_backend'-and!$j.weights_written-and$j.checkpoints.Count-eq0) 'training plan never fabricates running weights or checkpoints'
 Check ((Api '/api/memory-workshop').jobs[0].id-eq$training.id) 'new tasks are inserted at the front'
 $null=Api '/api/memory-workshop/control' @{id=$task.id;action='up'};Check ((Api '/api/memory-workshop').jobs[0].id-eq$task.id) 'queue ordering can be changed independently of execution'
 $null=Api '/api/memory-workshop/control' @{id=$task.id;action='pause'};Stop-Backend;Start-Backend;Check ((Job $task.id).status-eq'paused'-and(Job $task.id).completed_steps-eq0) 'paused distillation and its cursor survive restart'
 $null=Api '/api/control' @{paused=$true};$null=Api '/api/memory-workshop/control' @{id=$task.id;action='resume'};Await {(Job $task.id).status-in@('completed','failed')} distillation
 $j=Job $task.id;Check ($j.status-eq'completed'-and$j.completed_steps-eq$j.total_steps-and$j.checkpoints.Count-eq$j.total_steps) 'mock distillation publishes derived records with per-record recovery points'
 $summaries=@((Api '/api/memories').memories|Where-Object origin -eq library_compaction);Check ($summaries.Count-ge4) 'derived summaries coexist with original archives'
 foreach($id in $ids){$raw=(Api '/api/archive' @{id=$id}).records[0];Check ($raw.revision-eq1-and$raw.data.text.StartsWith('WORKSHOP_ORIGINAL_')) 'original text and revision remain intact'}
 $view=Api '/api/memory-workshop';Check (!($view|ConvertTo-Json -Depth 60).Contains('WORKSHOP_ORIGINAL_')-and!($view.jobs|Where-Object type -eq distill).PSObject.Properties['last_result']) 'management job status reveals no original or digest contents'
 $null=Api '/api/memory-workshop/control' @{id=$training.id;action='pause'};Check ((Job $training.id).status-eq'paused') 'a future training plan can be paused'
 $null=Api '/api/memory-workshop/control' @{id=$training.id;action='resume'};Check ((Job $training.id).status-eq'awaiting_backend') 'resuming a plan waits for an actual backend'
 $null=Api '/api/memory-workshop/control' @{id=$training.id;action='cancel'};Check ((Job $training.id).status-eq'cancelled') 'cancelling a plan retains its history'
 $extra=Create lora @{plan=$plan};$null=Api '/api/memory-workshop/control' @{id=$extra.id;action='cancel'};$archived=Api '/api/memory-workshop/control' @{id=$extra.id;action='archive'};Check ($archived.record_preserved-and!(Job $extra.id)) 'finished job history can be tucked away without deleting its stored record'
 # A local provider tests a real in-flight cancellation without any paid API.
 $null=Api '/api/control' @{paused=$false};$more=@();foreach($i in 1..3){$more+=Message ("WORKSHOP_SECOND_$i "+('另一个故事仍未结束，不能把别人的感受改成自己的。'*55))};foreach($i in 1..3){$null=Message "换个话题$i"};$null=Api '/api/control' @{paused=$true}
 $providerRoot=Join-Path $root provider;New-Item -ItemType Directory $providerRoot|Out-Null;$provider=Start-Process -FilePath $ProviderExecutable -ArgumentList ('"'+$providerRoot+'"') -WindowStyle Hidden -PassThru;Await {Test-Path (Join-Path $providerRoot port)} provider
 $digest=@{summary='合成故事里的说法仍有分歧，没有确认结论。';keywords=@('合成故事','分歧');uncertainties=@('仅测试受控提炼流程。')}
 @{responses=@(@{response=$digest;delay_ms=700})}|ConvertTo-Json -Depth 20|Set-Content (Join-Path $providerRoot plan.json) -Encoding utf8
 $settings=(Api '/api/dashboard').settings;$settings.profiles+=@{id='workshop-manager';label='local fixture';enabled=$true;protocol='chat-completions';origin=('http://127.0.0.1:'+(Get-Content (Join-Path $providerRoot port)));basePath='/v1';model='fixture-model';supportsJsonObject=$true;timeoutMs=10000;maxOutputTokens=2048};$settings.review=@{enabled=$true;profileId='workshop-manager';maxRewrites=0};$null=Api '/api/settings' @{settings=$settings}
 $slow=Create distill @{limit=128;minBytes=2000};Await {(Job $slow.id).completed_steps-ge1} 'first durable distillation step';$null=Api '/api/memory-workshop/control' @{id=$slow.id;action='pause'};Await {(Job $slow.id).status-eq'paused'} 'pause in-flight distillation';$cursor=(Job $slow.id).completed_steps;Check ($cursor-ge1-and$cursor-lt(Job $slow.id).total_steps) 'pause retains completed steps while cancelling later work'
 Stop-Backend;Start-Backend;Check ((Job $slow.id).completed_steps-eq$cursor-and(Job $slow.id).status-eq'paused') 'completed cursor persists through an actual restart'
 @{responses=@(@{response=$digest;delay_ms=0});nonce=[Guid]::NewGuid().ToString()}|ConvertTo-Json -Depth 20|Set-Content (Join-Path $providerRoot plan.json) -Encoding utf8
 $null=Api '/api/memory-workshop/control' @{id=$slow.id;action='resume'};Await {(Job $slow.id).status-in@('completed','failed')} 'resume distillation';Check ((Job $slow.id).status-eq'completed') 'remaining records continue from saved steps'
 $null=Api '/api/control' @{offline=$true;paused=$true};$drafts=Join-Path $cfg.dataRoot drafts;[IO.File]::WriteAllText((Join-Path $drafts (('长'*100)+'.txt')),'LONG_UNICODE_DRAFT');foreach($i in 1..60){[IO.File]::WriteAllText((Join-Path $drafts "test-$i.txt"),'WORKSHOP_DRAFT')};$secrets=Join-Path $cfg.dataRoot runtime/secrets;New-Item -ItemType Directory -Force $secrets|Out-Null;[IO.File]::WriteAllText((Join-Path $secrets unused.dpapi),'SYNTHETIC_API_CREDENTIAL_EXCLUDED');$nestedSecret=Join-Path $cfg.dataRoot 'channels/fake/private/owner/Runtime/SeCrEtS';New-Item -ItemType Directory -Force $nestedSecret|Out-Null;[IO.File]::WriteAllText((Join-Path $nestedSecret nested.dpapi),'SYNTHETIC_NESTED_SECRET');[IO.File]::WriteAllText((Join-Path $drafts keep-wal),'ORDINARY_USER_DRAFT')
 $backup=Create backup;Await {(Job $backup.id).completed_steps-ge1} 'backup checkpoint';$null=Api '/api/memory-workshop/control' @{id=$backup.id;action='pause'};Await {(Job $backup.id).status-eq'paused'} 'backup paused';$null=Api '/api/memory-workshop/control' @{id=$backup.id;action='resume'};Await {(Job $backup.id).status-in@('completed','failed')} backup 60
 $j=Job $backup.id;Check ($j.status-eq'completed') 'Unicode and apostrophe backup path completes with atomic SQLite snapshots'
 $manifest=Get-Content (Join-Path $j.path manifest.json) -Raw|ConvertFrom-Json;Check ($manifest.complete-and!$manifest.api_credentials_included-and$manifest.restore_requires_same_windows_user) 'backup manifest records actual completion and key constraints'
 Check (!(Test-Path (Join-Path $j.path data/runtime/secrets/unused.dpapi))-and!(Test-Path (Join-Path $j.path data/runtime/service.lock))) 'API credentials and live service lock are excluded'
 Check (!(Test-Path (Join-Path $j.path data/channels/fake/private/owner/Runtime/SeCrEtS/nested.dpapi))) 'nested channel API secrets are excluded independent of Windows directory case'
 Check ((Get-Content (Join-Path $j.path data/drafts/keep-wal) -Raw)-eq'ORDINARY_USER_DRAFT') 'ordinary user files with a database-like suffix are preserved'
 foreach($entry in $manifest.files){Check ((Get-FileHash (Join-Path $j.path $entry.path) -Algorithm SHA256).Hash-eq$entry.sha256) 'each backup entry matches its manifest hash'}
 $settings=(Api '/api/dashboard').settings;$settings.memoryWorkshop.backupRoot=Join-Path $root 'another-backup-folder';$null=Api '/api/settings' @{settings=$settings}
 $settings=(Api '/api/dashboard').settings;$settings.computer=@{enabled=$false;readRoots=@(@{id='backup';path=$cfg.memoryWorkshop.backupRoot})};Error-Code '/api/settings' @{settings=$settings} 400
 $messageCount=(Api '/api/state').messages.Count;Stop-Backend
 $recovered=Join-Path $root recovered-data;Copy-Item -LiteralPath (Join-Path $j.path data) -Destination $recovered -Recurse;$cfg.dataRoot=$recovered;$cfg|ConvertTo-Json -Depth 60|Set-Content $configPath -Encoding utf8;Start-Backend
 Check ((Api '/api/state').messages.Count-eq$messageCount-and(Api '/api/state').stage.id-eq'initial') 'independent restored archive decrypts conversations and stage with its saved key'
 Check ((Api '/api/memory-workshop').jobs.Count-ge4) 'restored archive retains completed and unfinished task history'
 Stop-Backend;Check (!([Text.Encoding]::UTF8.GetString([IO.File]::ReadAllBytes((Join-Path $recovered archive/records.sqlite))).Contains('WORKSHOP_ORIGINAL_'))) 'original dialogue and summaries remain encrypted on disk'
 @{completed=$true;checks=$checks;root=$root;actual_paid_model_calls=0}|ConvertTo-Json|Set-Content (Join-Path $root acceptance.json);Write-Output "Memory workshop passed: $checks checks. Evidence: $root"
}finally{foreach($p in @($service,$provider)){if($p){$p.Refresh();if(!$p.HasExited){Stop-Process -Id $p.Id}}}}
